class Solution:
    def reorderLogFiles(self, logs: list[str]) -> list[str]:
        digitLogs = []
        letterLogs = []
        for log in logs:
            l = log.split()
            if l[1].isnumeric():
                digitLogs.append(log)
            else:
                letterLogs.append(l)
        letterLogs.sort(key=lambda x: x[1:] + [x[0]])
        for i in range(len(letterLogs)):
            letterLogs[i] = " ".join(letterLogs[i])
        return letterLogs + digitLogs
